"""Versioned website analytics disclosure; English text is explicitly marked on all editions."""
import re
CONTROLS = '''<details class="analytics-choice" lang="en" dir="ltr"><summary>Website analytics · <span data-analytics-state>Basic</span></summary><p>Basic visitor counts use Vercel. With your permission, PostHog measures visits, approximate location, clicks and time on pages, and records masked website interactions for replay and heatmaps. No app accounts or call content. You can stop all website analytics here.</p><div><a href="/privacy.html?lang=en#website-analytics" lang="en">Analytics privacy (English)</a> · <button type="button" data-analytics-allow>Allow detailed analytics</button><button type="button" data-analytics-deny>Turn all analytics off</button></div></details>'''
BANNER = '''<aside id="website-analytics-banner" class="website-analytics-banner" lang="en" dir="ltr" aria-label="Website analytics choices" hidden><strong>Help improve the website</strong><p>Allow PostHog to measure visits, clicks, approximate location and time on pages, with masked session replay and heatmaps? Forms and call content are excluded. Basic Vercel visitor counts are already on.</p><div><button type="button" data-analytics-allow>Allow detailed analytics</button><button type="button" data-analytics-deny>Decline analytics</button><a href="/privacy.html?lang=en#website-analytics">Privacy (English)</a></div></aside>'''
POLICY = '''<section lang="en" dir="ltr" data-website-analytics-policy="20261013"><h2 id="website-analytics">Website analytics — updated October 13, 2026 (English)</h2>
<p>This section replaces the earlier website-analytics description. It applies to public marketing pages in every website language. App analytics and advertising measurement have separate controls below.</p>
<h3 id="vercel-analytics">Basic visitor measurement: Vercel</h3>
<p>Basic Vercel Web Analytics starts automatically on eligible public pages. It measures page views, approximate visitors, referring sites, country/region/city estimates, browser and device information, and App Store button clicks. Vercel derives a visitor hash from network information and discards it within 24 hours; it is not a permanent identity. We remove URL queries and fragments from events. This measurement uses no advertising cookies and does not record website sessions. Selecting Decline analytics or Turn all analytics off, or sending Global Privacy Control or Do Not Track, stops future website analytics. Counts are estimates and may exclude blocked visits.</p>
<h3>Detailed website analytics: PostHog</h3>
<p>PostHog (US hosting) starts only after you select Allow detailed analytics. It measures page views and exits, referring domains, device/browser/operating-system information, approximate location derived from network information, navigation and App Store clicks, scroll depth, active time, video engagement, and performance. A random browser identifier and session identifier connect activity across pages and repeat visits using browser local storage. They are not linked to your Dial Santa app account. The PostHog project is configured to discard raw IP addresses.</p>
<p>Detailed analytics also includes click and scroll heatmaps and masked session replay of the public website. Replay reconstructs page layout and interactions; it does not record your camera, microphone or calls. Inputs and editable or designated sensitive text are masked; public marketing copy remains visible. Forms, editable areas, embedded frames, canvas, video/audio content and designated sensitive elements are blocked. Network request bodies, headers and console logs are not recorded. New replays are retained for 30 days. Checkout, confirmation and private routes are excluded. We strip query strings and fragments and do not send names, email addresses, child profiles, form entries or call content.</p>
<p>Earlier permission for basic counts does not authorize detailed analytics or replay: we ask again. You can change your choice in the website footer. Turning analytics off stops future collection and clears PostHog's local tracking persistence; it does not erase data already received. Browser privacy signals take priority. Anonymous website measurements are separate from app analytics, purchases and advertising. For questions or deletion requests, contact <a href="mailto:hohoho@dialsanta.app">hohoho@dialsanta.app</a>. <a href="https://vercel.com/docs/analytics/privacy-policy">Vercel privacy details</a> · <a href="https://posthog.com/docs/privacy">PostHog privacy details</a>.</p></section>'''
def apply_analytics_markup(html, public=True):
    html = re.sub(r'<details\b[^>]*class="analytics-choice"[^>]*>.*?</details>', lambda m:CONTROLS, html, flags=re.S)
    html = re.sub(r'<aside\b[^>]*id="website-analytics-banner".*?</aside>', '', html, flags=re.S)
    if public and 'data-analytics-state' in html:
        html = html.replace('</body>', BANNER+'\n</body>')
    if 'data-analytics-state' in html and '/analytics.css' not in html:
        html = html.replace('</head>','<link rel="stylesheet" href="/analytics.css?v=20261013"/>\n</head>')
    html = re.sub(r'/acquisition\.js(?:\?v=[^"\s]+)?', '/acquisition.js?v=20261013-full', html)
    if 'id="website-analytics"' in html:
        html = re.sub(r'<div class="date"[^>]*>.*?</div>', '<div class="date" lang="en" dir="ltr">Effective October 13, 2026 (English analytics update)</div>', html, flags=re.S)
        html = re.sub(r'<section lang="en" dir="ltr" data-website-analytics-policy="20261013">.*?</section>', lambda m:POLICY, html, flags=re.S)
        if 'data-website-analytics-policy' not in html:
            html = re.sub(r'<h2\b[^>]*id="website-analytics"[^>]*>.*?(?=<h2\b[^>]*id="app-analytics")',lambda m:POLICY+'\n',html,flags=re.S)
    return html
